import { createHmac, timingSafeEqual } from 'node:crypto';
import { mkdir, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { env } from '../../config/env.js';
import type { StorageDriver } from './types.js';

export const UPLOAD_DIR = path.resolve('uploads');

/** Keys are generated by the API: households/<uuid>/<uuid>.<ext> or users/<uuid>/<uuid>.<ext> (profile photos). */
export const STORAGE_KEY_PATTERN = /^(households|users)\/[0-9a-f-]{36}\/[0-9a-f-]{36}\.(jpg|png|webp|pdf)$/;

const sign = (key: string, expires: number) =>
  createHmac('sha256', env.JWT_SECRET).update(`file:${key}:${expires}`).digest('base64url');

export function filePath(key: string) {
  return path.join(UPLOAD_DIR, key);
}

/** Checks the signature and expiry of a URL made by getSignedUrl. */
export function verifySignature(key: string, expires: number, signature: string): boolean {
  if (!STORAGE_KEY_PATTERN.test(key) || !Number.isFinite(expires) || expires < Date.now() / 1000) return false;
  const expected = Buffer.from(sign(key, expires));
  const given = Buffer.from(signature);
  return expected.length === given.length && timingSafeEqual(expected, given);
}

/** Development storage: files in uploads/, served by GET /api/files/* with a short-lived HMAC signature. */
export const localDriver: StorageDriver = {
  async put(key, body) {
    const target = filePath(key);
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, body);
  },

  async delete(key) {
    await rm(filePath(key), { force: true });
  },

  async getSignedUrl(key, expiresInSeconds) {
    const expires = Math.floor(Date.now() / 1000) + expiresInSeconds;
    // Relative URL: the browser reaches it through the web app's /api rewrite.
    return `/api/files/${key}?expires=${expires}&sig=${sign(key, expires)}`;
  },
};
